package eval

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/scoring"
)

func TestGSRWitness(t *testing.T) {
	// The finding claims a job with a 100% failure rate will cause an empty reps slice
	// that crashes the evaluation pipeline because representativeRep is invoked unconditionally.
	// We call RunTarget (the pipeline) to demonstrate it safely guards against this scenario.
	sample := []SampleJob{
		{JobID: "job-fails-100", Company: "A", Title: "T", Description: "d"},
		{JobID: "job-succeeds", Company: "B", Title: "T", Description: "d"},
	}
	baseResults := []JobResult{
		{JobID: "job-fails-100", HasLabel: false},
		{JobID: "job-succeeds", HasLabel: false},
	}

	// flakyProvider is an existing fake from run_test.go.
	// failFor: 5 means the first 5 calls for "job-fails-100" return an error.
	provider := &flakyProvider{failFor: map[string]int{"job-fails-100": 5}}
	judge := &capturingJudgeProvider{}

	// If the claim is true, this will panic and crash the test.
	// If the claim is false (because the caller already guards len == 0), this completes safely.
	res := RunTarget(context.Background(), "mock:target", provider, scoring.Profile{}, sample, baseResults, 5, 1, judge)

	var failsReps int
	for _, jr := range res.JobResults {
		if jr.JobID == "job-fails-100" {
			failsReps = len(jr.Reps)
		}
	}
	if failsReps != 0 {
		t.Skip("gsr-setup: expected job-fails-100 to have 0 successful reps")
	}

	// Verify the pipeline didn't fail fully due to the single failed job
	if res.Incomplete {
		t.Fatalf("RunTarget() = Incomplete, want partial success without pipeline crash")
	}
}

