import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/scoring"
)

func TestGSRWitness(t *testing.T) {
	var gotBudget int32 = -1
	body := mustJSONString(t, `{"matchScore":50,"reasons":[],"whyItFits":"x"}`)

	budget := 100
	p, err := newProviderWithHTTPClient(
		scoring.Config{Model: "gemini-3.5-flash", APIKey: "test-key", MaxTokens: 100, ThinkingBudget: &budget},
		&http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
			gotBudget = captureThinkingBudget(t, req)
			return jsonResponse(200, strings.ReplaceAll(canonicalGenerateContentResponse, "%s", body)), nil
		})},
	)
	if err != nil {
		t.Skipf("gsr-setup: newProviderWithHTTPClient: %v", err)
	}

	_, err = p.ScoreJob(context.Background(), scoring.JobInput{}, scoring.Profile{})
	if err != nil {
		t.Skipf("gsr-setup: ScoreJob: %v", err)
	}

	if gotBudget == 100 {
		t.Fatalf("call(MaxTokens=100, ThinkingBudget=100) sent thinkingBudget = %d, want < 100", gotBudget)
	}
}

