import (
	"context"
	"html/template"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strconv"
	"strings"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/recruiter"
	"github.com/weitzer-org/job_tracker/internal/storage"
)

func TestGSRWitness(t *testing.T) {
	oldTemplates := templates
	defer func() { templates = oldTemplates }()
	// Override the template to just print the field we want to assert on
	templates = template.Must(template.New("").Parse(`{{define "recruiterContactRow"}}{{.OtherAssessments}}{{end}}`))

	mem := storage.NewMemoryClient()
	srv := &Server{
		Contacts: &recruiter.Store{Storage: mem, Bucket: "test-bucket"},
	}

	ctx := context.Background()
	_, err := srv.Contacts.Mutate(ctx, "https://linkedin.com/in/nobody", func(c recruiter.Contact) recruiter.Contact {
		c.ProfileURL = "https://linkedin.com/in/nobody"
		// Deliberately empty Assessments map
		return c
	})
	if err != nil {
		t.Skip("gsr-setup: failed to seed contact: " + err.Error())
	}

	form := url.Values{
		"profileUrl": {"https://linkedin.com/in/nobody"},
		"field":      {"contacted"},
		"value":      {"true"},
	}
	req := httptest.NewRequest(http.MethodPatch, "/recruiter/contacts", strings.NewReader(form.Encode()))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()

	srv.handleRecruiterContactPatch(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("handleRecruiterContactPatch returned %d, want 200", w.Code)
	}

	got := strings.TrimSpace(w.Body.String())
	val, err := strconv.Atoi(got)
	if err != nil {
		t.Fatalf("unexpected template output: %q (err: %v)", got, err)
	}

	if val < 0 {
		t.Fatalf("OtherAssessments = %d, want >= 0", val)
	}
}

