	// Setup a contact with an uninitialized/empty Assessments map.
	_, err := srv.Contacts.Mutate(ctx, "https://linkedin.com/in/test", func(c recruiter.Contact) recruiter.Contact {
		c.Name = "Test"
		c.Assessments = nil // empty
		return c
	})
	if err != nil {
		t.Skipf("gsr-setup: failed to setup contact: %v", err)
	}

	form := url.Values{
		"profileUrl": {"https://linkedin.com/in/test"},
		"field":      {"contacted"},
		"value":      {"true"},
	}
	req := httptest.NewRequest(http.MethodPatch, "/recruiter/contacts", strings.NewReader(form.Encode()))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()

	h.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Skipf("gsr-setup: expected 200, got %d: %s", w.Code, w.Body.String())
	}

	got := strings.TrimSpace(w.Body.String())
