	oldTemplates := templates
	defer func() { templates = oldTemplates }()

	templates = template.Must(template.New("recruiterContactRow").Parse(`{{.OtherAssessments}}`))

	srv, h, _ := newTestRecruiterServer(t)
	ctx := context.Background()

	// Seed a contact with an explicitly empty Assessments map
	if _, err := srv.Contacts.Mutate(ctx, "https://linkedin.com/in/empty", func(c recruiter.Contact) recruiter.Contact {
		c.Name = "Empty"
		c.Assessments = nil // empty map
		return c
	}); err != nil {
		t.Skip("gsr-setup: seeding contact failed:", err)
	}

	form := url.Values{"profileUrl": {"https://linkedin.com/in/empty"}, "field": {"contacted"}, "value": {"true"}}
	req := httptest.NewRequest(http.MethodPatch, "/recruiter/contacts", strings.NewReader(form.Encode()))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	w := httptest.NewRecorder()
	h.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Skip("gsr-setup: handler returned non-200:", w.Code, w.Body.String())
	}

	// Check the evaluated value passed to the template
	got := strings.TrimSpace(w.Body.String())
	if got == "-1" {
		t.Fatalf("handleRecruiterContactPatch with empty assessments rendered OtherAssessments = %q, want >= 0", got)
