)

type gsrWitnessReader struct {
	srv    *Server
	reader io.Reader
}

func (r *gsrWitnessReader) Read(p []byte) (n int, err error) {
	// Mutate the bucket *after* pipeline.Run completes.
	// In handleIngest, the only thing that reads the request body is r.ParseForm(),
	// which executes exactly between pipeline.Run and readJobs.
	r.srv.StorageBucket = "bad-bucket"
	return r.reader.Read(p)
}

func TestGSRWitness(t *testing.T) {
	orig := log.Writer()
	defer log.SetOutput(orig)

	var logBuf bytes.Buffer
	log.SetOutput(&logBuf)

	mem := storage.NewMemoryClient()
	ctx := t.Context()

	// 1. Setup valid initial bucket so pipeline.Run succeeds
	validBuckets := []byte(`[{"name":"Bucket A","searches":[{"label":"Bucket A (NYC)","url":"https://nyc"}]}]`)
	if err := mem.WriteFile(ctx, "test-bucket", bucketsObjectKey, validBuckets, storage.IfNotExists); err != nil {
		t.Skip("gsr-setup: valid buckets:", err)
	}
	validJobs := []byte(`[]`)
	if err := mem.WriteFile(ctx, "test-bucket", jobsObjectKey, validJobs, storage.IfNotExists); err != nil {
		t.Skip("gsr-setup: valid jobs:", err)
	}

	// 2. Setup bad bucket to break readJobs during out-of-band refresh
	if err := mem.WriteFile(ctx, "bad-bucket", jobsObjectKey, []byte(`{invalid}`), storage.IfNotExists); err != nil {
		t.Skip("gsr-setup: bad bucket:", err)
	}

	provider, err := scoring.New(scoring.Config{MockMode: true, Model: "mock-model"})
	if err != nil {
		t.Skip("gsr-setup: scoring:", err)
	}

	srv := &Server{
		Storage:       mem,
		StorageBucket: "test-bucket",
		Status:        &status.Store{Storage: mem, Bucket: "test-bucket"},
		Apify: &ingest.MockApifyClient{Listings: []ingest.RawListing{
			{JobID: "new-1", JobTitle: "PM", CompanyName: "X", JobURL: "http://x", Location: "NY", JobDescription: "y"},
		}},
		ScoringProvider: provider,
		Profile:         scoring.Profile{Text: "profile", Version: "v1"},
	}

	body := &gsrWitnessReader{
		srv:    srv,
		reader: strings.NewReader("showStale=1"),
	}

	req := httptest.NewRequest("POST", "/ingest", body)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()

	srv.handleIngest(w, req)

	if logBuf.Len() == 0 {
		t.Fatalf("handleIngest() with failing readJobs logged nothing, want logged error")
	}
}

