	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	data []byte
	etag string
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if f.data == nil {
		return nil, "", storage.ErrNotFound
	}
	return f.data, f.etag, nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if ifMatch == storage.IfNotExists {
		if f.data != nil {
			return storage.ErrETagMismatch
		}
	} else if ifMatch != f.etag {
		return storage.ErrETagMismatch
	}
	f.data = append([]byte(nil), data...)
	f.etag = f.etag + "-updated"
	return nil
}

func TestGSRWitness(t *testing.T) {
	st := &gsrWitnessFakeStorage{
		data: []byte("this is definitely not valid JSON"),
		etag: "v1",
	}
	c := &CachingApifyClient{
		Storage: st,
		Bucket:  "test-bucket",
	}

	err := c.writeEntry(context.Background(), "my-key", cacheEntry{})
	if err != nil {
		t.Fatalf("writeEntry(...) = %v, want nil error", err)
	}
}

