func TestGSRWitness(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPost && strings.Contains(r.URL.Path, "/runs") {
			w.WriteHeader(http.StatusCreated)
			w.Write([]byte(`{"data":{"id":"run-123","status":"READY"}}`))
			return
		}
		if r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/actor-runs/") {
			w.WriteHeader(http.StatusOK)
			w.Write([]byte(`{"data":{"id":"run-123","status":"FAILED","defaultDatasetId":"dataset-123","usageTotalUsd":0.01}}`))
			return
		}
		if r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/datasets/") {
			w.WriteHeader(http.StatusOK)
			w.Write([]byte(`[]`))
			return
		}
		w.WriteHeader(http.StatusNotFound)
	}))
	defer srv.Close()

	var obs ApifyRunStats
	client := &ApifyRESTClient{
		Token:             "dummy",
