type gsrWitnessFakeStorage struct {
	storage.Client
	cancel  context.CancelFunc
	written bool
}

func (s *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if s.cancel != nil {
		s.cancel()
	}
	// Use context.Background() to ensure the read itself doesn't fail due to our cancellation.
	// This ensures we reach the WriteFile call where the bug manifests.
	return s.Client.ReadFile(context.Background(), bucket, key)
}

func (s *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	err := s.Client.WriteFile(ctx, bucket, key, data, ifMatch)
	if err == nil {
		s.written = true
	}
	return err
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	mem := storage.NewMemoryClient()
	// Pre-populate so it actually has a job to update.
	err := mem.WriteFile(context.Background(), "test-bucket", jobsObjectKey, []byte(`[{"jobId":"gsr-job-1","title":"Witness PM"}]`), "")
	if err != nil {
		t.Skip("gsr-setup: failed to seed memory client")
	}

	fs := &gsrWitnessFakeStorage{
		Client: mem,
		cancel: cancel,
	}

	p := &Pipeline{
		Storage:       fs,
		StorageBucket: "test-bucket",
		Provider:      mustProvider(t),
		Now:           time.Now,
	}

	jobs := []Job{
		{JobID: "gsr-job-1", Title: "Witness PM"},
	}

	// This call processes the job successfully, hits the `if !ok` block when the channel closes,
	// and calls flushUpgrades. Our fake cancels the context midway during the read, which verifies
	// whether UpgradeScores detached the context for the final flush as it should have.
	p.UpgradeScores(ctx, jobs)

	if !fs.written {
		t.Fatalf("fs.written = %v, want %v", fs.written, true)
	}
}

package ingest

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/scoring"
	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessMockStorage struct {
	storage.Client
	cancel context.CancelFunc
	data   []byte
}

func (m *gsrWitnessMockStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	// Cancel the parent context exactly when the storage read begins.
	// This deterministically exposes whether flushUpgrades was passed the raw context (which will now fail)
	// or a protected context via context.WithoutCancel (which will succeed).
	if m.cancel != nil {
		m.cancel()
	}
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	if m.data == nil {
		return nil, "", storage.ErrNotFound
	}
	return m.data, "etag", nil
}

func (m *gsrWitnessMockStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	m.data = data
	return nil
}

type gsrWitnessMockProvider struct {
	scoring.Provider
}

func (gsrWitnessMockProvider) ScoreJob(ctx context.Context, input scoring.JobInput, profile scoring.Profile) (scoring.Score, error) {
	return scoring.Score{MatchScore: 99}, nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	initialJobs := []Job{{JobID: "job-1", Title: "Test Job"}}
	data, err := json.Marshal(initialJobs)
	if err != nil {
		t.Skipf("gsr-setup: marshal failed: %v", err)
	}

	st := &gsrWitnessMockStorage{
		cancel: cancel,
		data:   data,
	}

	p := &Pipeline{
		Storage:       st,
		StorageBucket: "test-bucket",
		Provider:      gsrWitnessMockProvider{},
	}

	// UpgradeScores will spin up the worker, process the 1 job, and close the results channel.
	// This triggers the !ok block in its select loop, which calls flushUpgrades.
	p.UpgradeScores(ctx, initialJobs)

	var resultJobs []Job
	if err := json.Unmarshal(st.data, &resultJobs); err != nil {
		t.Fatalf("gsr-setup: unmarshal failed: %v", err)
	}

	if len(resultJobs) == 0 || resultJobs[0].MatchScore != 99 {
		t.Fatalf("UpgradeScores flush = %+v, want job with MatchScore 99 (context cancellation should not abort the final flush)", resultJobs)
	}
}
